// Extract Payload v5.4
const raw = $input.first().json.body || $input.first().json;

let persona = {};
try {
  const p = raw.persona;
  persona = typeof p === 'string' ? JSON.parse(p) : (p || {});
} catch(e) { persona = {}; }

const userId = raw.userId || persona.userId || '';
persona.userId = userId;
persona.language_preference = persona.language_preference || 'th';
persona.tokens   = persona.tokens   || {};
persona.relevant_memories = persona.relevant_memories || [];
persona.key_facts  = persona.key_facts  || [];
persona.interests  = persona.interests  || [];
persona.ethical_profile = persona.ethical_profile || null;

console.log(`[WF2 Extract] userId=${userId.substring(0,8)}... | lang=${persona.language_preference}`);

return {
  json: {
    userId,
    sessionId:       raw.sessionId,
    source:          raw.source || 'chat',
    message:         raw.message || '',
    originalMessage: raw.originalMessage || raw.message || '',
    timestamp:       raw.timestamp || new Date().toISOString(),
    replyTarget:     raw.replyTarget,
    replyToken:      raw.replyToken,
    databaseUrl:     raw.databaseUrl || '',
    persona,
    rawPayload:      raw
  }
};

// Prepare OpenRouter Body v5.4
// แยก logic ออกมา — node นี้แค่ build body + ตรวจ key
const payload = $input.first().json;
const message = payload.message || '';
const persona = payload.persona || {};
const lang    = persona.language_preference || 'th';
const name    = persona.name || 'User';
const tier    = persona.subscriptionTier || 'FREE';
const stage   = persona.ethical_profile?.growth_stage || 2;
const stageLabel = persona.ethical_profile?.growth_stage_label || 'Developing';
const interests  = (persona.interests || []).slice(0, 5).join(', ') || 'not specified';
const keyFacts   = (persona.key_facts || []).slice(0, 3).join(' | ') || 'none';
const recentMem  = (persona.relevant_memories || []).map(m => m.type).join(', ') || 'none';

// Key priority: user token → env var
const userKey = persona.tokens?.openrouter_access_token || '';
const rawEnv  = $env.OPENROUTER_API_KEY || '';
const sysKey  = (typeof rawEnv === 'string' && rawEnv.length > 10) ? rawEnv : '';
const apiKey  = userKey || sysKey || '';
const hasKey  = apiKey.length > 0;

const model = userKey
  ? 'anthropic/claude-haiku-4-5'
  : 'meta-llama/llama-3.3-70b-instruct:free';

const n8nBase = $env.N8N_BASE_URL || 'http://localhost:5678';
const AGENT_URLS = {
  wf3a: $env.N8N_WF3A_URL || `${n8nBase}/webhook/wf3a-secretary`,
  wf3b: $env.N8N_WF3B_URL || `${n8nBase}/webhook/wf3b-soul`,
  wf3c: $env.N8N_WF3C_URL || `${n8nBase}/webhook/wf3c-careercoach`,
  wf3d: $env.N8N_WF3D_URL || `${n8nBase}/webhook/wf3d-explorer`,
  wf3e: $env.N8N_WF3E_URL || `${n8nBase}/webhook/wf3e-creator`,
  wf3f: $env.N8N_WF3F_URL || `${n8nBase}/webhook/wf3f-homemate`,
  wf3g: $env.N8N_WF3G_URL || `${n8nBase}/webhook/wf3g-healthcoach`
};

const SYSTEM_PROMPT = `You are JARVIS — the central cognitive router of an advanced personal AI system.
Your function: Decompose the user's message into a structured dispatch plan.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
AGENT REGISTRY
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

wf3a [SECRETARY] — Calendar, reminders, email, social media, tasks
wf3b [SOUL] — Emotions, journaling, personal growth, crisis
wf3c [CAREER COACH] — Finance, investment, career
wf3d [EXPLORER] — Web search, news, weather, maps
wf3e [CREATOR] — Image gen, TTS, creative writing, translation
wf3f [HOME MATE] — Music, smart home
wf3g [HEALTH COACH] — Nutrition, fitness

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
- Output ONLY valid JSON, no markdown
- crisis → wf3b, crisis=true always
{
  "intents": [{
    "agent": "wf3x",
    "priority": 1,
    "sub_task": "instruction",
    "gating": false,
    "crisis": false
  }]
}

CONTEXT: User=${name} | Lang=${lang} | Tier=${tier} | Growth=${stage}/5 (${stageLabel})
Interests: ${interests} | Key facts: ${keyFacts} | Recent memories: ${recentMem}`;

console.log(`[Prepare] hasKey=${hasKey} | key_source=${userKey?'user':sysKey?'env':'none'}`);

return {
  json: {
    ...payload,
    _hasKey: hasKey,
    _orKey:  apiKey,
    _orBody: {
      model,
      max_tokens: 300,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user',   content: message }
      ]
    },
    _orModel:     model,
    _agentUrls:   AGENT_URLS,
    _keyType:     userKey ? 'user' : (sysKey ? 'system' : 'none')
  }
};

// Parse & Route v5.4
// รับ output จาก Call OpenRouter (มี choices) หรือ Has API Key? false branch
const item = $input.first().json;
const message  = item.message || '';
const persona  = item.persona || {};
const lang     = persona.language_preference || 'th';
const AGENT_URLS = item._agentUrls || {};
const usedModel  = item._orModel || null;
const keyType    = item._keyType  || 'none';

// OpenRouter response อยู่ใน choices (จาก HTTP Request node)
const choices = item.choices || null;
const rawText = choices?.[0]?.message?.content || null;

function parseIntents(text) {
  const VALID = ['wf3a','wf3b','wf3c','wf3d','wf3e','wf3f','wf3g'];
  try {
    if (!text) throw new Error('no text');
    const clean  = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);
    const intents = parsed.intents || parsed;
    const arr = Array.isArray(intents) ? intents : [intents];
    const validated = arr
      .filter(i => i && VALID.includes(i.agent))
      .map(i => ({
        agent:    i.agent,
        priority: [1,2,3].includes(i.priority) ? i.priority : 1,
        sub_task: i.sub_task || message,
        gating:   i.gating === true,
        crisis:   i.crisis  === true
      }))
      .sort((a, b) => a.priority - b.priority)
      .slice(0, 3);
    const seen = new Set();
    const deduped = validated.filter(i => {
      if (seen.has(i.agent)) return false;
      seen.add(i.agent); return true;
    });
    if (deduped.length === 0) throw new Error('empty');
    return deduped;
  } catch(e) {
    return [keywordRoute(message, lang)];
  }
}

function keywordRoute(msg, lang) {
  const t = msg.toLowerCase();
  if (/อยากตาย|ฆ่าตัว|สิ้นหวัง|want to die|hopeless/.test(t))
    return { agent: 'wf3b', priority: 1, sub_task: msg, gating: true, crisis: true };
  if (/นัด|ปฏิทิน|เตือน|ส่ง email|ส่งเมล|แจ้งเตือน|remind|calendar|schedule/.test(t))
    return { agent: 'wf3a', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/หุ้น|กองทุน|งบ|เงิน|ลงทุน|resume|สัมภาษณ์|career|invest/.test(t))
    return { agent: 'wf3c', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/ค้นหา|ค้น|ข่าว|สภาพอากาศ|แผนที่|search|weather|news/.test(t))
    return { agent: 'wf3d', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/รูปภาพ|สร้างรูป|แปล|image|translate|tts|เสียง/.test(t))
    return { agent: 'wf3e', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/เพลง|spotify|music|บ้าน|home assistant/.test(t))
    return { agent: 'wf3f', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/อาหาร|แคล|ออกกำลัง|สุขภาพ|nutrition|workout|calorie/.test(t))
    return { agent: 'wf3g', priority: 1, sub_task: msg, gating: false, crisis: false };
  // Default → wf3b (conversation / soul)
  return { agent: 'wf3b', priority: 1, sub_task: msg, gating: false, crisis: false };
}

const intents   = parseIntents(rawText);
const primary   = intents[0];
const hasCrisis = intents.some(i => i.crisis);

console.log(`[Parse & Route] agent=${primary.agent} | via=${rawText?'openrouter':'keyword'} | crisis=${hasCrisis}`);

return {
  json: {
    ...item,
    message:          primary.sub_task,
    originalMessage:  message,
    targetAgent:      primary.agent,
    targetUrl:        AGENT_URLS[primary.agent],
    needsGating:      primary.gating,
    hasCrisis,
    _intents:         intents,
    _dispatch_mode:   'single',
    _router_model:    rawText ? usedModel : null,
    _router_key_type: keyType,
    _router_version:  'v5.4',
    // cleanup
    choices:    undefined,
    _hasKey:    undefined,
    _orKey:     undefined,
    _orBody:    undefined,
    _orModel:   undefined,
    _agentUrls: undefined,
    _keyType:   undefined
  }
};

// Format Response v5.4
const raw = $input.first().json;
const msg = raw.message || raw.response || raw.output || raw.agentOutput || raw.text
            || 'ขออภัย ไม่สามารถตอบได้ในขณะนี้ครับ';

console.log(`[WF2 Response] agent=${raw._primary_agent || raw.targetAgent} | len=${String(msg).length}`);

return {
  json: {
    message:        msg,
    response:       msg,
    output:         msg,
    userId:         raw.userId,
    sessionId:      raw.sessionId,
    _primary_agent: raw._primary_agent || raw.targetAgent,
    _router_model:  raw._router_model,
    _router_version:'v5.4',
    _dispatch_mode: raw._dispatch_mode,
    hasCrisis:      raw.hasCrisis || false
  }
};
